// 2024年4月22日 - 2025年1月28日 22:21 除夕 5
// interlocking
// https://www.shadertoy.com/view/X3GGW3

float PI =3.1415926535;
#define rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))
vec4 clr;


float sdTest(vec3 p) 
{
        vec3 a = normalize(sqrt(vec3(.5-.1*sqrt(5.), 0., .5+.1*sqrt(5.)))),
             b = a.yzx, 
             c = a.zxy,
             e = normalize(vec3(1)),  
             //f = e + (b-e) * .4,  
             ac = normalize(a-c),ba,
             az = c,
             ay = ba = normalize(b-a), 
             ax = normalize(cross(az, ay)),
             n = normalize(cross(cross(e,a), b+c));             

        float sg = 1., md = 1e8, x, y, ang,r = .08, v;
        // 正二十面体的旋转折叠
        #define RF if(dot(p, n)<0.)p=reflect(p, n),sg=-sg;
        for(int i;i++<9;n=n.yzx)
              RF
        n=ba; RF
        n=ac; RF
        n=ba; RF

        for(int i;i++<2;p=p.zxy)
        {
                vec2 w = vec2(dot(p, ax), dot(p, ay));
                y = dot(p, az)-.7;
                x = length(w);
                ang = atan(w.y, w.x);
                v = sin(sg * ang * 5.+.4);
                x = x - .7 - v*r;         
                md = min(md, sqrt(x*x+y*y));
        }
        return md-r; 
}

float map(vec3 p)
{
        float t = iTime+3.3;
        p.xy *= rot(t   );
        p.yz *= rot(t*.7);
        p.zx *= rot(t*.3);
        return sdTest(p);
}

void mainImage(out vec4 O, vec2 U)
{
        O = vec4(.83); clr++;
        vec2 R = iResolution.xy,
             u = (U+U - R) / R.y;
        if(dot(u,u)>.7)return;//
        vec3 eye = vec3(0, 0, -3),
             dir = normalize(vec3(u, 2)),
             sun = 5. * ( .2*cos(iTime+vec3(7,11,13)) + vec3(-1,2,-3)/3.74 ),
             eps = vec3(0, .0001, 0),
             nor, p;
        float d , t;
        for(int i; i++<128 && t<6.;)
        {
                p = eye + dir * t;
                d = map(p);
                if( d<.01 )
                {       // phong 光照模型
                        nor = normalize(vec3(map(p+eps.yxx), map(p+eps), map(p+eps.xxy))-d); 
                        vec3  sp = normalize(sun-p), ep=normalize(eye-p);
                        float ln = max(0., dot(nor,sp)),               // light norm
                              er = max(0., dot(ep, reflect(-sp,nor))); // eye ray
                        float ambt=.3, difu=.6, spec=80.;
                        vec4  lightClr = vec4(er*.1,ln*.7,.9,1);O = lightClr * (ambt + difu*ln + pow(er, spec));O *= clr;
                        break;
                }
                t += d * .8;
        }
        O = O.yzxw;
}
